import fs from 'fs/promises';
import path from 'path';
import { glob } from 'glob';
import { loadAll as loadAllYaml, CORE_SCHEMA } from 'js-yaml';
import { detect, type Agent } from 'package-manager-detector';
import { errnoCode } from '../utils/errnoCode';
import { isPathWithinRoot } from '../utils/pathContainment';
import type { FailureReasonCode } from '../utils/failureReason';

export type PreviewPackageManager = 'npm' | 'yarn' | 'pnpm';

export class PackageManagerError extends Error {
  constructor(
    readonly reasonCode: FailureReasonCode,
    message: string,
  ) {
    super(message);
    this.name = 'PackageManagerError';
  }
}

export interface ProjectPackageManager {
  name: PreviewPackageManager;
  agent: Agent;
  version?: string;
  rootPath: string;
  packagePaths: string[];
  hasLockfile: boolean;
}

interface PackageManifest {
  packageManager?: string;
  workspaces?: string[] | { packages?: string[] };
  devEngines?: { packageManager?: { name?: string; version?: string } };
}

interface PnpmWorkspace {
  packages?: string[];
}

export const LOCKFILES: Record<PreviewPackageManager, string[]> = {
  npm: ['package-lock.json', 'npm-shrinkwrap.json'],
  yarn: ['yarn.lock'],
  pnpm: ['pnpm-lock.yaml'],
};

export const INSTALL_CONFIG_FILES: Record<PreviewPackageManager, string[]> = {
  npm: ['.npmrc'],
  yarn: ['.yarnrc', '.yarnrc.yml'],
  pnpm: ['pnpm-workspace.yaml', '.pnpmfile.cjs'],
};

export const INSTALL_ARTIFACTS: Record<PreviewPackageManager, string[]> = {
  npm: ['node_modules', 'node_modules/.package-lock.json'],
  yarn: [
    'node_modules',
    '.pnp.cjs',
    '.pnp.loader.mjs',
    '.yarn/install-state.gz',
  ],
  pnpm: ['node_modules', 'node_modules/.modules.yaml'],
};

export const INSTALL_CONTENT_GLOBS: Record<PreviewPackageManager, string[]> = {
  npm: ['patches/**/*'],
  yarn: ['.yarn/patches/**/*', '.yarn/plugins/**/*', '.yarn/releases/**/*'],
  pnpm: ['patches/**/*'],
};

const INSTALL_OUTPUTS: Record<PreviewPackageManager, string[]> = {
  npm: ['node_modules'],
  yarn: [
    'node_modules',
    '.pnp.cjs',
    '.pnp.loader.mjs',
    '.yarn/install-state.gz',
    '.yarn/unplugged',
  ],
  pnpm: ['node_modules'],
};

export const forEveryPackageManager = (
  record: Record<PreviewPackageManager, string[]>,
): string[] => [...new Set(Object.values(record).flat())];

const INSTALL_OUTPUT_SEGMENTS = forEveryPackageManager(INSTALL_OUTPUTS).map(
  (output) => output.split('/'),
);

export const isInstallOutputPath = (relativePath: string): boolean => {
  const parts = relativePath.split(path.sep);
  return INSTALL_OUTPUT_SEGMENTS.some((output) =>
    parts.some((_, index) =>
      output.every((segment, offset) => parts[index + offset] === segment),
    ),
  );
};

const isPreviewPackageManager = (
  value: string,
): value is PreviewPackageManager =>
  value === 'npm' || value === 'yarn' || value === 'pnpm';

const parsePackageManagerDeclaration = (
  declared: string,
): { name: PreviewPackageManager; version: string } | null => {
  const separator = declared.indexOf('@');
  if (separator <= 0) return null;
  const name = declared.slice(0, separator);
  const [version] = declared.slice(separator + 1).split('+', 1);
  if (!isPreviewPackageManager(name) || version.length === 0) return null;
  return { name, version };
};

export const readProjectFile = async (file: string): Promise<string | null> => {
  try {
    return await fs.readFile(file, 'utf8');
  } catch (error) {
    if (errnoCode(error) === 'ENOENT') return null;
    throw error;
  }
};

const readManifest = async (root: string): Promise<PackageManifest | null> => {
  const source = await readProjectFile(path.join(root, 'package.json'));
  if (source === null) return null;
  try {
    return JSON.parse(source) as PackageManifest;
  } catch {
    throw new PackageManagerError(
      'invalid_manifest',
      'package.json is not valid JSON',
    );
  }
};

const readPnpmWorkspace = (source: string): PnpmWorkspace | null => {
  try {
    return (loadAllYaml(source, { schema: CORE_SCHEMA })[0] ??
      null) as PnpmWorkspace | null;
  } catch {
    throw new PackageManagerError(
      'invalid_workspace',
      'pnpm-workspace.yaml is not valid YAML',
    );
  }
};

const packagePathsFor = async (
  root: string,
  manifest: PackageManifest,
): Promise<string[]> => {
  const pnpmSource = await readProjectFile(
    path.join(root, 'pnpm-workspace.yaml'),
  );
  const pnpmConfig = pnpmSource === null ? null : readPnpmWorkspace(pnpmSource);
  const patterns =
    pnpmConfig?.packages ??
    (Array.isArray(manifest.workspaces)
      ? manifest.workspaces
      : manifest.workspaces?.packages) ??
    [];
  if (
    !Array.isArray(patterns) ||
    patterns.some((pattern) => typeof pattern !== 'string')
  ) {
    throw new PackageManagerError(
      'invalid_workspace',
      'Workspace packages must be an array of directory patterns',
    );
  }
  const included = patterns.filter((pattern) => !pattern.startsWith('!'));
  const excluded = patterns
    .filter((pattern) => pattern.startsWith('!'))
    .map((pattern) => `${pattern.slice(1)}/**`);
  const files = await glob(
    included.map((pattern) => `${pattern}/package.json`),
    {
      cwd: root,
      absolute: true,
      nodir: true,
      ignore: ['**/node_modules/**', '**/.git/**', '**/.rivet/**', ...excluded],
    },
  );
  const members = await Promise.all(
    files.map((file) => fs.realpath(path.dirname(file))),
  );
  if (members.some((member) => !isPathWithinRoot(root, member))) {
    throw new PackageManagerError(
      'path_outside_workspace',
      'A workspace package resolves outside the preview workspace',
    );
  }
  return [...new Set([root, ...members.sort()])];
};

export const resolveProjectPackageManager = async (options: {
  cwd: string;
  workspaceRoot: string;
  packageManagerCommand?: string;
}): Promise<ProjectPackageManager | null> => {
  const cwd = await fs.realpath(options.cwd);
  const boundary = await fs.realpath(options.workspaceRoot);
  if (!isPathWithinRoot(boundary, cwd)) {
    throw new PackageManagerError(
      'path_outside_workspace',
      'Dependency preparation directory is outside the preview workspace',
    );
  }
  let rootPath = cwd;
  let manifest = await readManifest(cwd);
  if (!manifest) return null;
  let packagePaths = await packagePathsFor(cwd, manifest);
  for (
    let parent = path.dirname(cwd);
    isPathWithinRoot(boundary, parent) && parent !== cwd;
    parent = path.dirname(parent)
  ) {
    const parentManifest = await readManifest(parent);
    if (parentManifest) {
      const members = await packagePathsFor(parent, parentManifest);
      if (members.includes(cwd)) {
        rootPath = parent;
        manifest = parentManifest;
        packagePaths = members;
        break;
      }
    }
    if (parent === boundary) break;
  }

  const declared = manifest.packageManager;
  const declaration = declared ? parsePackageManagerDeclaration(declared) : null;
  if (declared && !declaration) {
    throw new PackageManagerError(
      'invalid_package_manager_field',
      `Unsupported packageManager declaration: ${declared}. Preview preparation supports pinned npm, Yarn, and pnpm versions.`,
    );
  }
  const managersWithLockfiles: PreviewPackageManager[] = [];
  for (const name of Object.keys(LOCKFILES) as PreviewPackageManager[]) {
    const contents = await Promise.all(
      LOCKFILES[name].map((file) => readProjectFile(path.join(rootPath, file))),
    );
    if (contents.some((content) => content !== null))
      managersWithLockfiles.push(name);
  }
  const commandName = options.packageManagerCommand
    ? path.basename(options.packageManagerCommand).replace(/\.cmd$/i, '')
    : '';
  const commandManager = isPreviewPackageManager(commandName)
    ? commandName
    : null;
  const selectedManager =
    !declared &&
    !manifest.devEngines?.packageManager &&
    managersWithLockfiles.length > 1 &&
    commandManager &&
    managersWithLockfiles.includes(commandManager)
      ? commandManager
      : null;
  if (
    !declared &&
    !manifest.devEngines?.packageManager &&
    managersWithLockfiles.length > 1 &&
    !selectedManager
  ) {
    throw new PackageManagerError(
      'multiple_lockfiles',
      'Multiple package manager lockfiles found. Set package.json packageManager to select the project tool.',
    );
  }
  const detected = selectedManager
    ? null
    : await detect({
        cwd: rootPath,
        stopDir: rootPath,
        strategies: ['packageManager-field', 'devEngines-field', 'lockfile'],
      });
  const name = selectedManager ?? detected?.name ?? 'npm';
  if (name !== 'npm' && name !== 'yarn' && name !== 'pnpm') {
    throw new PackageManagerError(
      'unsupported_package_manager',
      `Preview dependency preparation does not support ${name}`,
    );
  }
  let agent: Agent = selectedManager ?? detected?.agent ?? name;
  if (
    name === 'yarn' &&
    (await readProjectFile(path.join(rootPath, 'yarn.lock')))?.includes(
      '__metadata:',
    )
  ) {
    agent = 'yarn@berry';
  }
  return {
    name,
    agent,
    rootPath,
    packagePaths,
    version: declaration?.version,
    hasLockfile: managersWithLockfiles.includes(name),
  };
};
